// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 sequenceNumber_,
        bytes32 batcherHash_,
        uint256 l1FeeOverhead_,
        uint256 l1FeeScalar_
    ) public {
        // Domain stays wide: all block values are fully fuzzed, no constraint.
        // The call is authorized by the contract's actual depositor account,
        // so setL1BlockValues completes its body on both P and M.
        address depositor = c.depositorAccount();
        vm.prank(depositor);
        c.setL1BlockValues(
            number_,
            timestamp_,
            basefee_,
            hash_,
            sequenceNumber_,
            batcherHash_,
            l1FeeOverhead_,
            l1FeeScalar_
        );
        // Rule: after any authorized call, c.l1FeeOverhead() is still 0
        // (P never writes any state; M stores _l1FeeOverhead).
        assertTrue(c.l1FeeOverhead() == 0);
    }
}
